code.java:
class Solution {
    public int minimumMoves(String s){
        int answer=0;
        for(int index=0;index<s.length();)if(s.charAt(index)=='X'){
            answer++;
            index+=3;
        }else index++;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun minimumMoves(s:String):Int{
        var index=0;
        var answer=0;
        while(index<s.length)if(s[index]=='X'){
            answer++;
            index+=3
        }else index++;
        return answer
    }
}

code.cpp:
class Solution {
    public: int minimumMoves(string s){
        int answer=0;
        for(int index=0;index<(int)s.size();)if(s[index]=='X'){
            ++answer;
            index+=3;
        }else ++index;
        return answer;
    }
};
